import os, sys
# Check environment for DB URL
for k, v in sorted(os.environ.items()):
    if 'DB' in k.upper() or 'POSTGRES' in k.upper() or 'PG' in k.upper():
        print(f'{k}={v}')
print('---')
# Check if we can find the host
import socket
try:
    print(f'Hostname: {socket.gethostname()}')
except:
    pass
try:
    print(f'Hosts: {socket.gethostbyname_ex(socket.gethostname())}')
except:
    pass
# Try common hostnames
for host in ['localhost', '127.0.0.1', 'host.docker.internal', 'postgres', 'pgvector', 'testvdb-db']:
    try:
        ip = socket.gethostbyname(host)
        print(f'{host} -> {ip}')
    except:
        print(f'{host} -> UNRESOLVABLE')
